mapper.update:
UPDATE diet_chat_request
SET status = 'COMPLETED', processing_token = NULL, response_json = #{responseJson},
    trace_id = #{traceId}, failure_code = NULL, updated_at = NOW()
WHERE user_id = #{userId} AND request_id = #{requestId}
  AND status = 'PROCESSING' AND processing_token = #{processingToken}

UPDATE diet_chat_request
SET status = 'FAILED', processing_token = NULL, failure_code = #{failureCode}, updated_at = NOW()
WHERE user_id = #{userId} AND request_id = #{requestId}
  AND status = 'PROCESSING' AND processing_token = #{processingToken}
